package com.aiservice.infrastructure.external;
import com.aiservice.application.port.out.TaxonomyImportPort;import com.aiservice.application.service.TextbookStructureService.Structure;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class TaxonomyImportRestClient implements TaxonomyImportPort{private final RestClient client;private final String base;public TaxonomyImportRestClient(RestClient.Builder builder,@Value("${question.service.url:http://question-service}")String base){this.client=builder.build();this.base=base;}public void confirm(UUID subjectId,Structure structure,String token){client.post().uri(base+"/api/v1/subjects/{id}/structure/import",subjectId).headers(h->h.setBearerAuth(token)).body(Map.of("chapters",structure.chapters())).retrieve().toBodilessEntity();}}
